import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Daten zwischen Schritten","description":"Ergebnisse vorheriger Schritte in späteren Schritten eines Flows verwenden.","frontmatter":{"title":"Daten zwischen Schritten","description":"Ergebnisse vorheriger Schritte in späteren Schritten eines Flows verwenden."},"headers":[],"relativePath":"flows/daten-zwischen-schritten.md","filePath":"flows/daten-zwischen-schritten.md","lastUpdated":1786434193000}'),i={name:"flows/daten-zwischen-schritten.md"};function s(l,e,d,o,h,c){return n(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="daten-zwischen-schritten" tabindex="-1">Daten zwischen Schritten <a class="header-anchor" href="#daten-zwischen-schritten" aria-label="Permalink to &quot;Daten zwischen Schritten&quot;">​</a></h1><p>Jeder Schritt eines Flows kann auf die Ergebnisse der vorherigen zugreifen. Das ist das Grundprinzip: Der <a href="/flows/trigger">Auslöser</a> liefert Daten, die erste Aktion arbeitet damit, die zweite nutzt deren Ergebnis.</p><h2 id="werte-einfugen" tabindex="-1">Werte einfügen <a class="header-anchor" href="#werte-einfugen" aria-label="Permalink to &quot;Werte einfügen&quot;">​</a></h2><p>In den Einstellungen eines Schritts führt <strong>Werte aus vorherigen Schritten verwenden</strong> zur Auswahl der verfügbaren Daten. Ein Klick setzt den Wert an die Einfügemarke; alternativ ziehen Sie ihn an die gewünschte Stelle im Textfeld.</p><p>Ein eingefügter Wert erscheint als farbiger Baustein. Ein Klick darauf öffnet den <a href="/apptivescript/editor">Ausdruckseditor</a> — dort lässt sich der Wert weiterverarbeiten, etwa umrechnen oder mit einem Ersatzwert versehen.</p><div class="tip custom-block"><p class="custom-block-title">Feste Texte und Werte mischen</p><p>Sie müssen sich nicht entscheiden. Ein E-Mail-Betreff kann lauten: <code>Ihre Anmeldung zu </code> gefolgt vom Feld <code>Veranstaltung</code> aus dem Auslöser. Das gilt für Empfänger, Betreff, Inhalt und die meisten anderen Eingabefelder.</p></div><div class="tip custom-block"><p class="custom-block-title">Im JavaScript-Schritt und im HTML-Block per Tastenkürzel</p><p>Diese beiden haben einen Code-Editor statt Bausteine. Dort fügt <strong>Strg + Leertaste</strong> Grid-Felder ein:</p><blockquote><p><em>Drücken Sie Strg + Leertaste um Grid-Felder einzufügen</em></p></blockquote><p>→ <a href="/apptivescript/editor#grid-felder-im-html-block-und-im-javascript-schritt">Der Ausdruckseditor</a></p></div><h2 id="was-der-ausloser-liefert" tabindex="-1">Was der Auslöser liefert <a class="header-anchor" href="#was-der-ausloser-liefert" aria-label="Permalink to &quot;Was der Auslöser liefert&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Auslöser</th><th>Verfügbare Daten</th></tr></thead><tbody><tr><td><strong>Neuer Eintrag</strong></td><td>Der neu angelegte Eintrag mit allen Feldern</td></tr><tr><td><strong>Eintrag wurde geändert</strong></td><td>Der geänderte Eintrag mit allen Feldern</td></tr><tr><td><strong>Eintrag per Formular</strong></td><td>Der angelegte Eintrag</td></tr><tr><td><strong>Eintrag per Formular geändert</strong></td><td>Der geänderte Eintrag</td></tr><tr><td><strong>Webhook</strong></td><td>Die übergebenen JSON-Daten</td></tr><tr><td><strong>Seite anzeigen</strong></td><td>Die auf der Seite eingegebenen Werte</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Alle Felder stehen zur Verfügung</p><p>Auch Felder, die im auslösenden Formular gar nicht abgefragt wurden, sind verfügbar — der Flow bekommt den vollständigen Eintrag, nicht nur die Formulareingaben.</p></div><h2 id="was-aktionen-liefern" tabindex="-1">Was Aktionen liefern <a class="header-anchor" href="#was-aktionen-liefern" aria-label="Permalink to &quot;Was Aktionen liefern&quot;">​</a></h2><p>Jede Aktion gibt ein Ergebnis weiter, das spätere Schritte verwenden können:</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Ergebnis</th></tr></thead><tbody><tr><td><strong>Alle Einträge laden</strong></td><td>Eine Liste von Einträgen</td></tr><tr><td><strong>Eintrag erstellen</strong></td><td>Der neu angelegte Eintrag</td></tr><tr><td><strong>QR Code</strong></td><td>Der erzeugte Code</td></tr><tr><td><strong>PDF zu Text</strong></td><td>Der ausgelesene Text</td></tr><tr><td><strong>CSV-Datei importieren</strong></td><td>Die eingelesenen Zeilen</td></tr><tr><td><strong>JavaScript</strong></td><td>Der Rückgabewert des Codes</td></tr><tr><td><strong>Link zu Seite erstellen</strong></td><td>Ein Link auf den laufenden Durchlauf</td></tr><tr><td><strong>Vorausgefüllter Formularlink</strong></td><td>Ein Bearbeitungslink</td></tr></tbody></table><h2 id="listen-brauchen-„parallel" tabindex="-1">Listen brauchen „Parallel&quot; <a class="header-anchor" href="#listen-brauchen-„parallel" aria-label="Permalink to &quot;Listen brauchen „Parallel&quot;&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Eine Liste ist noch keine Wiederholung</p><p>Liefert ein Schritt eine <strong>Liste</strong> — etwa <em>Alle Einträge laden</em> — führen die folgenden Schritte trotzdem nur <strong>einmal</strong> aus.</p><p>Erst der Helfer <strong>Parallel</strong> macht daraus einzelne Durchläufe je Element. → <a href="/flows/router-und-parallel">Router und Parallel</a></p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alle Einträge laden      →  Liste</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Parallel                 →  je Element einmal</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>E-Mail                   →  hier steht ein einzelner Eintrag zur Verfügung</span></span></code></pre></div><p>Innerhalb von <em>Parallel</em> beziehen Sie sich auf das <strong>aktuelle Element</strong>, nicht mehr auf die ganze Liste.</p><p>Mit <strong>Durchläufe zusammenführen</strong> endet der parallele Bereich: Danach läuft der Flow wieder einmalig, und Sie beziehen sich nicht mehr auf ein einzelnes Element. → <a href="/flows/router-und-parallel">Router und Parallel</a></p><h2 id="werte-aus-dem-javascript-schritt" tabindex="-1">Werte aus dem JavaScript-Schritt <a class="header-anchor" href="#werte-aus-dem-javascript-schritt" aria-label="Permalink to &quot;Werte aus dem JavaScript-Schritt&quot;">​</a></h2><p>Der <a href="/flows/aktionen">JavaScript-Schritt</a> erhält die Daten des vorherigen Schritts als <code>input</code> und gibt mit <code>return</code> weiter:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> input</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;processed&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Für Umformungen, die kein Schritt abdeckt</p><p>Wenn ein fremdes System ein bestimmtes Format erwartet oder Werte umgerechnet werden müssen, ist das der Weg dorthin — ohne einen eigenen Dienst zu betreiben.</p></div><h2 id="daten-aus-seiten" tabindex="-1">Daten aus Seiten <a class="header-anchor" href="#daten-aus-seiten" aria-label="Permalink to &quot;Daten aus Seiten&quot;">​</a></h2><p>Zeigt ein Flow eine <a href="/flows/seiten-in-flows">Seite</a> an, stehen die dort eingegebenen Werte danach zur Verfügung. Der Zugriff erfolgt über den <strong>Key</strong> des jeweiligen Eingabeblocks.</p><div class="warning custom-block"><p class="custom-block-title">Key festlegen, bevor Sie darauf verweisen</p><p>Ändern Sie den Key nachträglich, greifen bestehende Verweise ins Leere — ohne Fehlermeldung. → <a href="/seiten/eingabebloecke">Eingabeblöcke</a></p></div><p>Bei <a href="/seiten/html-bloecke">HTML-Blöcken mit Formularfeldern</a> gilt zusätzlich: Eingabefelder ohne <code>name</code>- oder <code>id</code>-Attribut werden <strong>nicht</strong> übergeben.</p><h2 id="wenn-werte-leer-ankommen" tabindex="-1">Wenn Werte leer ankommen <a class="header-anchor" href="#wenn-werte-leer-ankommen" aria-label="Permalink to &quot;Wenn Werte leer ankommen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache</th></tr></thead><tbody><tr><td>Leerer Wert in der E-Mail</td><td>Das Feld war im Eintrag nicht gefüllt</td></tr><tr><td>Verweis auf einen späteren Schritt</td><td>Nur vorherige Schritte sind verfügbar</td></tr><tr><td>Nach einem Router</td><td>Der andere Zweig wurde durchlaufen, seine Daten fehlen</td></tr><tr><td>Nach einer Seite</td><td>Der Key stimmt nicht oder wurde geändert</td></tr><tr><td>Aus einem HTML-Block</td><td><code>name</code>- oder <code>id</code>-Attribut fehlt</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Ansehen statt raten</p><p>Über <strong>Details anzeigen</strong> an einem Schritt sehen Sie dessen tatsächliche Ein- und Ausgabedaten aus einem echten Durchlauf. Das klärt fast jede Frage nach „warum ist das leer&quot; schneller als Nachdenken.</p><p>→ <a href="/flows/testen">Flows testen</a></p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/flows/aktionen">Aktionen</a></li><li><a href="/flows/router-und-parallel">Router und Parallel</a></li><li><a href="/flows/testen">Flows testen</a></li></ul>`,31)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
